import { defineConfig } from "vite";

import { dashboardEnv, renderConfigBlock } from "./env-config.mjs";

/**
 * Vite is only the development server/HMR workflow. Production is still generated by
 * build.mjs as one self-contained HTML file for the app's setup wizard.
 */
export default defineConfig(({ mode }) => {
  const config = dashboardEnv(mode);

  return {
    server: {
      port: 5173,
      strictPort: true,
    },
    plugins: [
      {
        name: "wasted-dev-entry",
        transformIndexHtml(html) {
          let devEntryFound = false;
          const withDevEntry = html.replace(
            /<script type="module" src="\/?assets\/app\.js" defer><\/script>/,
            () => {
              devEntryFound = true;
              return `<script type="module" src="/src/main.js?t=${Date.now()}"></script>`;
            },
          );
          if (!devEntryFound) {
            throw new Error(
              "Wasted dev entry not replaced; refusing to serve a stale assets/app.js bundle.",
            );
          }
          return withDevEntry
            .replace(
              "connect-src https://*.supabase.co wss://*.supabase.co;",
              "connect-src 'self' https://*.supabase.co wss://*.supabase.co " +
                "ws://localhost:* http://localhost:* ws://127.0.0.1:* http://127.0.0.1:*;",
            )
            .replace("<!-- __WASTED_CONFIG__ -->", () => renderConfigBlock(config));
        },
      },
    ],
  };
});
